	void Increase(float value);
};

template <class T>
class list
{
	struct node
	{
		node * next;
		node * previous;
		T value;
	};

	node * sentinel;

public:
	class reverse_iterator
	{
		node * current;

	public:
		reverse_iterator(node * value) : current(value) {}
		T & operator*() const { return current->previous->value; }
		reverse_iterator & operator++() { current = current->previous; return *this; }
		bool operator!=(const reverse_iterator & right) const { return current != right.current; }
	};

	reverse_iterator rbegin() { return reverse_iterator(sentinel); }
	reverse_iterator rend() { return reverse_iterator(sentinel->next); }
	bool empty() const { return sentinel->next == sentinel; }
};

class ScoringManager
{
public:
	enum ATTRIBUTE
	{
		ATTR_DIST_LIP,
		ATTR_DIST_MOUTH,
		ATTR_TIME_TOTAL,
		ATTR_TIME_DELTA
	};

	class Trick
	{
	public:
		enum TYPE { TYPE_TRICK, TYPE_GAP };
		TYPE type;
		int index;
		int flags;
		float time;
		int numSpins;
		float mouthDist;
		float lipDist;
		int repetitions;
	};

	typedef list<Trick> TrickList;

	class Series
	{
	public:
		void * levelTricks;
		TrickList tricks;
		int numSpins;
		int landing;
		int flags;
	};

	typedef list<Series> SeriesList;

	class Chain
	{
	public:
		void * levelTricks;
		float multAdder;
		SeriesList series;
		float GetSickness() const;
	};

private:
	char padding0[12];
	int playerIdx;
	SpecialMeter * specialMeter;
	char padding1[408];
	Chain chain;

public:
	void UpdateLastTrick(const ATTRIBUTE attr, const float f, const int flags);
};

